import React, { useContext, useEffect } from "react";
import { Link } from "react-router-dom";
import styled, { keyframes } from "styled-components";
import PageWrapper from "../components/PageWrapper";
import { ThemeContext } from "../components/ThemeContext";

// --- Animations ---
const fadeInUp = keyframes`
  0% { opacity: 0; transform: translateY(20px);}
  100% { opacity: 1; transform: translateY(0);}
`;

const gradientShift = keyframes`
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
`;

const HomeWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 60px;
  padding: 60px 20px;
  min-height: 100vh;
  transition: background 0.3s, color 0.3s;
`;

const Hero = styled.div`
  position: relative;
  border-radius: 16px;
  padding: 100px 40px;
  text-align: center;
  overflow: hidden;
  animation: ${fadeInUp} 0.8s ease forwards;

  &::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(270deg, #ff416c, #ff4b2b, #ff416c);
    background-size: 600% 600%;
    animation: ${gradientShift} 12s ease infinite;
    opacity: 0.15;
    z-index: 0;
  }
`;

const HeroTitle = styled.h1`
  font-size: 52px;
  margin-bottom: 20px;
  color: #e50914;
  position: relative;
  z-index: 1;
`;

const HeroSubtitle = styled.p`
  font-size: 20px;
  margin-bottom: 40px;
  color: ${({ darkMode }) => (darkMode ? "#ccc" : "#555")};
  position: relative;
  z-index: 1;
`;

const HeroButton = styled(Link)`
  background-color: #e50914;
  color: #fff;
  padding: 18px 40px;
  font-size: 20px;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 600;
  position: relative;
  z-index: 1;
  box-shadow: 0 6px 20px rgba(233, 9, 20, 0.5);
  transition: all 0.3s ease;

  &:hover {
    background-color: #ff1a2d;
    transform: translateY(-3px);
    box-shadow: 0 10px 30px rgba(233, 9, 20, 0.7);
  }
`;

const SectionGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 40px;
`;

const Card = styled(Link)`
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: 350px;
  border-radius: 16px;
  padding: 20px;
  color: #fff;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  box-shadow: ${({ darkMode }) =>
    darkMode
      ? "0 12px 30px rgba(0,0,0,0.7)"
      : "0 12px 30px rgba(0,0,0,0.25)"};
  transition: all 0.4s ease;

  &:hover {
    transform: scale(1.05);
  }

  &:before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(0deg, rgba(0,0,0,0.4), rgba(0,0,0,0.1));
    z-index: 0;
    transition: all 0.4s ease;
  }

  &:after {
    content: "";
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: rgba(255,255,255,0.1);
    transform: rotate(25deg) translateX(-100%);
    transition: all 0.7s ease;
    z-index: 2;
  }

  &:hover:after {
    transform: rotate(25deg) translateX(100%);
  }
`;

const CardContent = styled.div`
  position: relative;
  z-index: 3;
`;

const CardTitle = styled.h3`
  font-size: 26px;
  margin-bottom: 10px;
`;

const CardDescription = styled.p`
  font-size: 16px;
`;

// --- Color Gradients for Cards ---
const colors = [
  { bg1: "#ff7e5f", bg2: "#feb47b" }, // Add Book
  { bg1: "#6a11cb", bg2: "#2575fc" }, // My Books
  { bg1: "#43cea2", bg2: "#185a9d" }, // About
];

const Home = () => {
  const { darkMode } = useContext(ThemeContext);

  useEffect(() => {
    document.body.style.background = darkMode ? "#1e1e1e" : "#f5f5f5";
    document.body.style.color = darkMode ? "#e0e0e0" : "#121212";
  }, [darkMode]);

  return (
    <PageWrapper>
      <HomeWrapper>
        {/* HERO */}
        <Hero>
          <HeroTitle>Welcome to My Book Library 📚</HeroTitle>
          <HeroSubtitle darkMode={darkMode}>
            Discover, add, and manage your personal book collection effortlessly.
          </HeroSubtitle>
          <HeroButton to="/books">Explore Books</HeroButton>
        </Hero>

        {/* SECTION CARDS */}
        <SectionGrid>
          {colors.map((c, idx) => {
            const links = ["/add", "/mybooks", "/about"];
            const titles = ["Add a New Book", "My Book Collection", "About This App"];
            const descs = [
              "Add your personal collection quickly.",
              "View and manage all your books.",
              "Learn how to use the library efficiently."
            ];
            return (
              <Card
                key={idx}
                to={links[idx]}
                darkMode={darkMode}
                style={{
                  background: `linear-gradient(135deg, ${c.bg1}, ${c.bg2})`,
                }}
              >
                <CardContent>
                  <CardTitle>{titles[idx]}</CardTitle>
                  <CardDescription>{descs[idx]}</CardDescription>
                </CardContent>
              </Card>
            );
          })}
        </SectionGrid>
      </HomeWrapper>
    </PageWrapper>
  );
};

export default Home;
